.policy-container {
width: 100%;
height: 1000px;
padding: 10px;
background-color: #f9f9f9;
font-family: Sans-Serif;
color: #000;
}
.policy-title {
width: 800px;
padding: 10px 5px 0 5px;
margin: 0px auto;
font-size: 24px;
}
.policy {
width: 800px;
height:900px;
margin: 10px auto;
background: #fff;
color: #000;
border: 1px solid #ddd;
border-radius: 2px;
}
.policy textarea {
width: 100%;
height: 100%;
padding: 20px;
border: 0;
outline: 0;
}
textarea.noresize {
resize: none; /* 사용자 임의 변경 불가 */
}

@media (max-width: 767px) {
.policy {
width: 100%;
font-size: 13px;
}
}

$(window).bind("load",function(){
initPolicy(function() {
$("body").show();
});
});

function initPolicy(callback) {
qvjax_direct(
"select_terms",
"/module/member/member.php",
'',
function (data) {
if (data.length > 0) {
var m = "service";
var text = $.grep(data, function(e){ return e.stms_type == m; })[0].stms_txt;

$('.policy textarea').text(text);

switch(m) {
case 'service':
$('.policy-title').text(lang.terms_of_service);
break;
case 'privacy':
$('.policy-title').text(lang.privacy_policy);
break;
}

callback();
}
},
function (xhr) { }
);
}
